//! The Python text of a view. Which handle each entry gets is in `rust_view.rs`;
//! `gecode-iris`'s `python_views` test runs ruff, pyright and mypy on the output.
use gecode_iris_gen::{Language, view_code};
use gecode_iris_sema::analyze;
use gecode_iris_syntax::{LanguageVersion, parse};

fn code(source: &str) -> String {
    let parsed = parse(source.as_bytes(), "test.iris", LanguageVersion::V0_1).unwrap();
    view_code(&parsed, &analyze(&parsed), Language::Python).expect("the spec is accepted")
}

const HEADER: &str =
    "\"\"\"Typed handles of a reader spec, generated by `iris gen --lang python`.\"\"\"\n";

#[test]
fn python_has_a_view_printer() {
    assert!(Language::Python.has_view());
}

#[test]
fn a_spec_without_entries_prints_only_the_header() {
    assert_eq!(code("skip line\n"), HEADER);
}

#[test]
fn each_handle_type_gives_its_view() {
    let source = "n:int a[1]:float if n {s:word m[1][1]:num} x:int x:word";
    let expected = format!(
        "{HEADER}
import gecode_iris.build as ib

n = ib.declared(\"n\", ib.IntField[int])
a = ib.declared(\"a\", ib.FloatField[list[float]])
s = ib.declared(\"s\", ib.StrField[str | None])
m = ib.declared(\"m\", ib.NumField[list[list[int | float]] | None])
x = ib.declared(\"x\", ib.DynField)
"
    );
    assert_eq!(code(source), expected);
}

#[test]
fn an_entry_deeper_than_eight_is_dynamic() {
    let spec = |depth: usize| format!("{}v:int{}", "repeat 1 {".repeat(depth), "}".repeat(depth));
    let eight = format!("ib.IntField[{}int{}]", "list[".repeat(8), "]".repeat(8));
    assert!(code(&spec(8)).contains(&eight));
    assert!(code(&spec(9)).contains("v = ib.declared(\"v\", ib.DynField)\n"));
}

#[test]
fn identifiers_follow_the_builder_rules_without_a_leading_underscore() {
    let name = "n".repeat(30);
    let source = format!("if:int int:int b:int ib:int a_b:int _a_b:int {name}a:int {name}b:int");
    let text = code(&source);
    for (identifier, entry) in [
        ("if_", "if"),
        ("int_", "int"),
        ("b_", "b"),
        ("ib_", "ib"),
        ("a_b", "a_b"),
        ("a_b_2", "_a_b"),
    ] {
        let line = format!("{identifier} = ib.declared(\"{entry}\", ib.IntField[int])\n");
        assert!(text.contains(&line), "{line}in\n{text}");
    }
    let stored = code("repeat until \"E\" store _ {}");
    assert!(stored.contains("name = ib.declared(\"_\", ib.StrField[str])\n"));
    let short = "n".repeat(24);
    assert!(text.contains(&format!("{short} = ib.declared(\n    \"{name}a\",")));
    assert!(text.contains(&format!("{short}_2 = ib.declared(\n    \"{name}b\",")));
}

#[test]
fn a_declaration_breaks_as_ruff_breaks_a_call() {
    let fits = format!("{}:int", "x".repeat(24));
    assert!(code(&fits).ends_with(&format!(
        "{0} = ib.declared(\"{0}\", ib.IntField[int])\n",
        "x".repeat(24)
    )));

    let entry = "y".repeat(60);
    assert!(code(&format!("{entry}:int")).ends_with(&format!(
        "{} = ib.declared(\n    \"{entry}\", ib.IntField[int]\n)\n",
        "y".repeat(24)
    )));

    let entry = "z".repeat(80);
    assert!(code(&format!("{entry}:int")).ends_with(&format!(
        "{} = ib.declared(\n    \"{entry}\",\n    ib.IntField[int],\n)\n",
        "z".repeat(24)
    )));
}
